import axios from 'axios'
import router from '@/router'
import store from '@/store'
import { getToken } from '@/utils/auth'
import { showNotify } from 'vant';
// create an axios instance
// 'http://49.234.211.89:7500' 测试
const service = axios.create({
        // baseURL: 'https://www.topcloudtower.com', // url = base url + request url
        // withCredentials: true, // send cookies when cross-domain requests
        timeout: 25000 // request timeout
    })
    // request interceptor
// request interceptor
service.interceptors.request.use(
  config => {
    // 排除登录接口，不添加 Authorization header
    if (!config.url.endsWith('/tenantCodeLogin')) { // 假设登录接口 URL 是以 '/login' 结尾
      config.headers['Authorization'] = getToken()
    }
    return config
  },
  error => {
    return Promise.reject(error)
  }
)
service.interceptors.response.use(
    response => {
        const res = response.data;
        console.log(res)
        // if (!res.success) {
        //     let token = getToken();
        //     if (!token) {
        //         router.push({
        //             path: '/login',
        //             replace: true
        //         })
        //         return false
        //     }
        // }
        return res

    },
    error => {
        // showNotify({ type: 'warning', message: error.response.data.message });
        // router.push({
        //     path: '/login',
        //     replace: true
        // })
        return Promise.reject(error)
    }
)

export default service